#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Threading.Tasks;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
using UnityEngine.TestTools;
namespace LastRail.Tests.EditMode {
 public class BLocalFlowSourceContractTests {[Test]public void ACurrentPacketBridgeRequiresIndependentTrustedSourceHash(){Assert.IsNotNull(typeof(BLocalFlowCandidate).Assembly.GetType("LastRail.Battle.BLocalFlowSourcePacket"));}}
 public class BLocalFlowExecutionTests {
  static JObject bundle;BSelectionController selection;BRefitController refit;BSelectionHttpTransport st;BRefitHttpTransport rt;BSelectionConnection sc;BRefitConnection rc;
  [OneTimeSetUp]public void Intake(){var raw=Environment.GetEnvironmentVariable("LASTRAIL_B_SOURCE_PRIVATE");Environment.SetEnvironmentVariable("LASTRAIL_B_SOURCE_PRIVATE",null);if(string.IsNullOrEmpty(raw))Assert.Ignore("Private real source socket supervisor required");bundle=JObject.Parse(raw);}
  [OneTimeTearDown]public void Release()=>bundle=null;
  [TearDown]public void Close(){sc?.Dispose();rc?.Dispose();selection?.Dispose();refit?.Dispose();st?.Dispose();rt?.Dispose();}
  static IEnumerator Wait(Task t){while(!t.IsCompleted)yield return null;Assert.IsFalse(t.IsFaulted,"Safe source exchange");Assert.IsFalse(t.IsCanceled);}
  static IEnumerator Finished(Task t){while(!t.IsCompleted)yield return null;}
  static void Same(JToken a,JToken b)=>Assert.IsTrue(JToken.DeepEquals(a,b),"Original released source or run state preserved");
  static JObject Intake(string name,string kind=null){var full=(JObject)bundle[name].DeepClone();if(kind!=null){var h=(JObject)full["headers"];var key=kind=="selection"?"X-Combat-B-Selection-Version":"X-Combat-B-Refit-Version";full["headers"]=new JObject{["Authorization"]=h["Authorization"].DeepClone(),[key]=h[key].DeepClone()};}return full;}
  static BLocalFlowSourceHttpTransport Source(string name)=>new BLocalFlowSourceHttpTransport(new BLocalFlowSourcePrivateIntake(Intake(name)));
  static string Trusted(string name,int phase=0)=>(string)bundle["trusted"][name][phase];
  void Open(string name){st=new BSelectionHttpTransport(new BSelectionPrivateIntake(Intake(name,"selection")));rt=new BRefitHttpTransport(new BRefitPrivateIntake(Intake(name,"refit")));selection=new BSelectionController();refit=new BRefitController();sc=new BSelectionConnection(selection,st);rc=new BRefitConnection(refit,rt);}
  BLocalFlowCandidate Candidate()=>new BLocalFlowCandidate(st.AccountId,selection.State,refit.State,refit.OriginalRequest,refit.Receipt);
  static JArray Cells(int eveSlot=1,string type="BCB01")=>new JArray(Enumerable.Range(0,2).Select(slot=>new JObject{["slot"]=slot,["type"]=slot==eveSlot?type:"BCB06",["rank"]=1}));
  static BSelectionDefinition Swap(BSelectionSnapshot current){var d=current.Selection.Capture();var rows=(JArray)d["placements"];var first=rows[0]["occupant"].DeepClone();rows[0]["occupant"]=rows[1]["occupant"].DeepClone();rows[1]["occupant"]=first;return new BSelectionDefinition(d);}
  IEnumerator Saved(string name,bool prepared=false){Open(name);selection.Read();yield return Wait(sc.LastExchange);if(!prepared){selection.Save(Swap(selection.State),"first-selection");yield return Wait(sc.LastExchange);selection.Read();yield return Wait(sc.LastExchange);}Assert.AreEqual(2,selection.State.Revision);refit.Read();yield return Wait(rc.LastExchange);Assert.AreEqual(2,refit.State.SelectionRevision);refit.Save(Cells(),prepared?"existing-noop":"first-refit");yield return Wait(rc.LastExchange);if(refit.Receipt==null){Assert.AreEqual(503,refit.LastError.Status);refit.ReplayOriginal();yield return Wait(rc.LastExchange);}refit.Read();yield return Wait(rc.LastExchange);Assert.IsNull(refit.State.EligibilityError);}
  [UnityTest]public IEnumerator ActualSelectionRefreshAndRefitPacketDriveNativeEveHpAndR1TypeDifferenceThenPreserveOldRun(){
   yield return Saved("workflow");var first=Candidate();using var source=Source("workflow");using var one=new BLocalFlowSourceConnection(first,source,Trusted("workflow"));yield return Wait(one.ReadAsync());var packet=one.Packet;Assert.IsNotNull(packet);Assert.IsFalse(packet.StartReady);var loop=packet.CreateLoop(1000);var initialPacket=packet.Capture();var hit=loop.Advance("three",40010000,4001);CollectionAssert.AreEqual(new long[]{1,2001,4001},hit.Hits.Select(h=>h.Attack.Tick));CollectionAssert.AreEqual(new[]{28,28,28},hit.Hits.Select(h=>h.Attack.BeforeShield));Assert.AreEqual(616,loop.Hp("enemy"));Assert.AreEqual(1368,loop.Hp("op_eve"));CollectionAssert.Contains(packet.Binding.UnsuppliedActors.ToArray(),"enemy");
   refit.Save(Cells(type:"BCB02"),"second-refit");yield return Wait(rc.LastExchange);refit.Read();yield return Wait(rc.LastExchange);using var second=new BLocalFlowSourceConnection(Candidate(),Source("workflow"),Trusted("workflow",1));yield return Wait(second.ReadAsync());var noBonus=second.Packet.CreateLoop(1000);Assert.AreEqual(25,noBonus.Advance("one",10000,1).Hits[0].Attack.BeforeShield);Assert.AreEqual(675,noBonus.Hp("enemy"));var oldRun=loop.Capture();Same(initialPacket,packet.Capture());
   selection.Save(Swap(selection.State),"second-selection");yield return Wait(sc.LastExchange);selection.Read();yield return Wait(sc.LastExchange);Assert.AreEqual(3,selection.State.Revision);using var ineligible=new BLocalFlowSourceConnection(first,Source("workflow"),Trusted("workflow"));yield return Wait(ineligible.ReadAsync());Assert.AreEqual(409,ineligible.LastError.Status);Assert.IsNull(ineligible.Packet);refit.Read();yield return Wait(rc.LastExchange);Assert.AreEqual(3,refit.State.SelectionRevision);Assert.IsNotNull(refit.State.EligibilityError);refit.Save(Cells(0),"third-refit");yield return Wait(rc.LastExchange);refit.Read();yield return Wait(rc.LastExchange);using var third=new BLocalFlowSourceConnection(Candidate(),Source("workflow"),Trusted("workflow",2));yield return Wait(third.ReadAsync());Assert.AreEqual(0,(int)third.Packet.Capture()["attack"]["entities"].Single(e=>(string)e["id"]=="op_eve")["slot"]);Assert.AreEqual(28,third.Packet.CreateLoop(1000).Advance("new-run",10000,1).Hits[0].Attack.BeforeShield);Same(oldRun,loop.Capture());Same(initialPacket,packet.Capture());var restored=BDirectAttackBasicLoop.Restore(oldRun,packet.Binding,1000);restored.Advance("next",20000000,2000);loop.Advance("next",20000000,2000);Same(loop.Capture(),restored.Capture());
   File.WriteAllText((string)bundle["observationPath"],new JObject{["taskId"]="U-B-LOCAL-FLOW-10",["actualSavedAccount"]=first.AccountId,["selectionRevision"]=initialPacket["selectionRevision"].DeepClone(),["refitRevision"]=initialPacket["refitRevision"].DeepClone(),["actualPhysical"]=initialPacket["departure"].DeepClone(),["sourcePacketHash"]=packet.OriginalHash,["wireBuffHash"]=initialPacket["buffBindingHash"].DeepClone(),["nativeNormalizedBuffHash"]=packet.Binding.Composition.OriginalHash,["nativeNormalizedLoopHash"]=packet.Binding.OriginalHash,["automaticTicks"]=new JArray(hit.Hits.Select(h=>h.Attack.Tick)),["BCB01_R1_DAMAGE"]=28,["BCB02_R1_DAMAGE"]=25,["oldRunHpAfterThree"]=616,["nativeRestoreAfterNextHp"]=loop.Hp("enemy"),["rankDifference"]="NOT_RUN_SUPPLIER_R1_ONLY",["enemyAutomaticTarget"]="UNSUPPLIED",["startReady"]=false,["oldRunFrozenAcrossActualNextSelection"]=true}.ToString());
  }
  [UnityTest]public IEnumerator TrustedHashAndEveryCurrentIdentityBindingRejectTamperingWithoutPublishingPartialBattleState(){
   yield return Saved("boundary",true);var candidate=Candidate();using var source=Source("boundary");var read=source.ReadAsync();yield return Wait(read);var wire=read.Result.Body;var original=new BLocalFlowSourcePacket(candidate,wire,Trusted("boundary"));Assert.Throws<ArgumentException>(()=>new BLocalFlowSourcePacket(candidate,wire,"sha256:"+new string('a',64)));
   foreach(var field in new[]{"account","revision","physical","sourceHash","definitionHash","profile","attack","context","route","extra","version"}){var p=(JObject)wire.DeepClone();if(field=="account")p["accountId"]="b";if(field=="revision")p["selectionRevision"]=3;if(field=="physical")p["departure"]["cars"][0]["instanceId"]="foreign-physical";if(field=="sourceHash")p["sourceHash"]=new string('b',64);if(field=="definitionHash")p["definitionHash"]=new string('c',64);if(field=="profile")p["ownedProfile"]["accountId"]="b";if(field=="attack")p["attack"]["entities"].Single(e=>(string)e["id"]=="op_eve")["attack"]["numerator"]="999";if(field=="context")p["contextId"]="other-context";if(field=="route")p["routes"][0]["targetId"]="foreign-target";if(field=="extra")p["unexpected"]=1;if(field=="version")p["version"]="other-version";p.Remove("packetHash");var forged=BDirectAttackInput.Digest(p);p["packetHash"]=forged;Assert.Throws<ArgumentException>(()=>new BLocalFlowSourcePacket(candidate,p,Trusted("boundary")),"Self-recomputed digest is not independent trust");Assert.Throws<ArgumentException>(()=>new BLocalFlowSourcePacket(candidate,p,forged),"Even a trusted malformed publisher must fail domain checks");}Same(wire,original.Capture());var captured=original.Capture();captured["departure"]["cars"][0]["rank"]=5;Same(wire,original.Capture());Assert.AreEqual(28,original.CreateLoop(1000).Advance("valid",10000,1).Hits[0].Attack.BeforeShield);
  }
  [UnityTest]public IEnumerator ExtraPhysicalRollbackAndSparsePacketErrorsRemainExplicit(){
   yield return Saved("errors",true);var old=Candidate();using var source=Source("errors");var before=source.ReadAsync();yield return Wait(before);var d=selection.State.Selection.Capture();((JArray)d["placements"]).Add(new JObject{["slot"]=2,["carriageId"]="LOCAL_CAR",["occupant"]=new JObject{["kind"]="CARGO"}});selection.Save(new BSelectionDefinition(d),"extra-physical");yield return Wait(sc.LastExchange);Assert.AreEqual(409,selection.LastError.Status);selection.Read();yield return Wait(sc.LastExchange);Assert.AreEqual(2,selection.State.Revision);var after=source.ReadAsync();yield return Wait(after);Same(before.Result.Body,after.Result.Body);d=selection.State.Selection.Capture();foreach(var row in (JArray)d["placements"])row["slot"]=(int)row["slot"]+1;selection.Save(new BSelectionDefinition(d),"sparse");yield return Wait(sc.LastExchange);selection.Read();yield return Wait(sc.LastExchange);refit.Read();yield return Wait(rc.LastExchange);refit.Save(new JArray(new JObject{["slot"]=1,["type"]="BCB06",["rank"]=1},new JObject{["slot"]=2,["type"]="BCB01",["rank"]=1}),"sparse-refit");yield return Wait(rc.LastExchange);var sparse=source.ReadAsync();yield return Wait(sparse);Assert.AreEqual(409,sparse.Result.Status);Assert.AreEqual("combat_b_source_geometry_slots_unsupported",(string)sparse.Result.Body["errorCode"]);Assert.IsFalse(old.StartReady);Assert.AreEqual(0,source.InFlightCount+rt.InFlightCount+st.InFlightCount);
  }
  [UnityTest]public IEnumerator RestoredSameDatabaseOriginalReceiptAndFreshAuthRecreateTheExactOldBattleBinding(){
   yield return Saved("restored",true);var candidate=Candidate();using var source=Source("restored");using var connection=new BLocalFlowSourceConnection(candidate,source,Trusted("restored"));yield return Wait(connection.ReadAsync());Same(bundle["restoredPacket"],connection.Packet.Capture());var loop=connection.Packet.CreateLoop(1000);loop.Advance("before",40010000,4001);var restored=BDirectAttackBasicLoop.Restore(loop.Capture(),connection.Packet.Binding,1000);Same(loop.Capture(),restored.Capture());using var old=Source("old");var auth=old.ReadAsync();yield return Wait(auth);Assert.AreEqual(401,auth.Result.Status);var oldRead=new BRefitSnapshot((JObject)bundle["restoreBeforeRefit"],"a");var replay=rt.SendAsync(BRefitRequest.Save(oldRead,Cells(),"first-refit"));yield return Wait(replay);Same(bundle["restoreReceipt"],replay.Result.Body);loop.Advance("after",20000000,2000);restored.Advance("after",20000000,2000);Same(loop.Capture(),restored.Capture());Assert.AreEqual(588,restored.Hp("enemy"));
  }
  [UnityTest]public IEnumerator LostAcceptedRefitAcknowledgementRecoversOriginalKeyBeforeActualSourceAndHp(){yield return Saved("lost");var original=refit.OriginalRequest;var ack=refit.Receipt;using var source=Source("lost");using var connection=new BLocalFlowSourceConnection(Candidate(),source,Trusted("lost"));yield return Wait(connection.ReadAsync());Assert.AreEqual(28,connection.Packet.CreateLoop(1000).Advance("actual",10000,1).Hits[0].Attack.BeforeShield);refit.ReplayOriginal();yield return Wait(rc.LastExchange);Assert.AreSame(original,refit.OriginalRequest);Same(ack,refit.Receipt);}
  [UnityTest]public IEnumerator DisposeDuringActualSourceReadAbortsRequestAndNeverPublishesPacket(){yield return Saved("slow",true);var candidate=Candidate();var source=Source("slow");var connection=new BLocalFlowSourceConnection(candidate,source,Trusted("slow"));var read=connection.ReadAsync();yield return new UnityEngine.WaitForSecondsRealtime(.15f);connection.Dispose();yield return Finished(read);Assert.IsTrue(read.IsCanceled||read.IsFaulted);Assert.IsNull(connection.Packet);Assert.IsFalse(connection.InFlight);Assert.AreEqual(0,source.InFlightCount);using var fresh=Source("slow");using var reopened=new BLocalFlowSourceConnection(candidate,fresh,Trusted("slow"));yield return Wait(reopened.ReadAsync());Assert.AreEqual(28,reopened.Packet.CreateLoop(1000).Advance("actual",10000,1).Hits[0].Attack.BeforeShield);}
  [UnityTest]public IEnumerator ActualOtherAccountCannotUseThisAccountsTrustedPhysicalPacket(){yield return Saved("accountB",true);var candidate=Candidate();using var source=Source("accountB");using var own=new BLocalFlowSourceConnection(candidate,source,Trusted("accountB"));yield return Wait(own.ReadAsync());Assert.AreEqual("b",(string)own.Packet.Capture()["accountId"]);Assert.AreEqual("b_physical2",(string)own.Packet.Capture()["departure"]["cars"][1]["instanceId"]);using var foreign=Source("boundary");Assert.Throws<ArgumentException>(()=>new BLocalFlowSourceConnection(candidate,foreign,Trusted("boundary")));var response=foreign.ReadAsync();yield return Wait(response);Assert.Throws<ArgumentException>(()=>new BLocalFlowSourcePacket(candidate,response.Result.Body,Trusted("boundary")));Assert.AreEqual(28,own.Packet.CreateLoop(1000).Advance("b-only",10000,1).Hits[0].Attack.BeforeShield);}
 }
